from app.core.resources import display_rows

"""Certificate Signatures endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .service import Service

TABLE = "certificate_signatures"
router = APIRouter(prefix="/certificate-signatures", tags=["Certificate Signatures"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.certificate_code,
       t.signing_provider,
       t.key_reference,
       t.signature_algorithm,
       t.signed_document_storage_key,
       t.document_sha256,
       t.signed_by_employee_code,
       t.signed_at,
       t.revoked_at,
       t.signature,
       t.public_key,
       x.data AS extras
FROM certificate_signatures AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'certificate_signatures' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.certificate_code,
       t.signing_provider,
       t.key_reference,
       t.signature_algorithm,
       t.signed_document_storage_key,
       t.document_sha256,
       t.signed_by_employee_code,
       t.signed_at,
       t.revoked_at,
       t.signature,
       t.public_key,
       x.data AS extras
FROM certificate_signatures AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'certificate_signatures' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO certificate_signatures (
    code,
    certificate_code,
    signing_provider,
    key_reference,
    signature_algorithm,
    signed_document_storage_key,
    document_sha256,
    signed_by_employee_code,
    signed_at,
    revoked_at,
    signature,
    public_key
)
VALUES (
    %(code)s,
    %(certificate_code)s,
    %(signing_provider)s,
    %(key_reference)s,
    %(signature_algorithm)s,
    %(signed_document_storage_key)s,
    %(document_sha256)s,
    %(signed_by_employee_code)s,
    %(signed_at)s,
    %(revoked_at)s,
    %(signature)s,
    %(public_key)s
)
"""

UPDATE_SQL = """
UPDATE certificate_signatures
SET certificate_code = %(certificate_code)s,
    signing_provider = %(signing_provider)s,
    key_reference = %(key_reference)s,
    signature_algorithm = %(signature_algorithm)s,
    signed_document_storage_key = %(signed_document_storage_key)s,
    document_sha256 = %(document_sha256)s,
    signed_by_employee_code = %(signed_by_employee_code)s,
    signed_at = %(signed_at)s,
    revoked_at = %(revoked_at)s,
    signature = %(signature)s,
    public_key = %(public_key)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM certificate_signatures
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = None
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)
